private val Ink=Color(0xFF071018); private val Panel=Color(0xFF0D1822); private val Raised=Color(0xFF12212D); private val Line=Color(0xFF223541); private val Txt=Color(0xFFF4F8FA); private val Muted=Color(0xFF91A4AF); private val Green=Color(0xFF35D07F); private val Red=Color(0xFFFF5E68); private val Cyan=Color(0xFF28B7D9)
private val Scheme=darkColorScheme(primary=Cyan,secondary=Green,background=Ink,surface=Panel,surfaceVariant=Raised,onBackground=Txt,onSurface=Txt,outline=Line,error=Red)
private object Keys { val ACCOUNT=stringPreferencesKey("account_id"); val SESSION=stringPreferencesKey("session_token"); val BROKER=stringPreferencesKey("broker"); val SERVER=stringPreferencesKey("server"); val LOGIN=stringPreferencesKey("login") }
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{App(applicationContext)}}}
@Composable private fun App(c:Context){var tab by remember{mutableStateOf(0)};MaterialTheme(colorScheme=Scheme){Scaffold(containerColor=Ink,bottomBar={NavigationBar(containerColor=Panel){listOf("Home" to Icons.Default.Home,"Strategies" to Icons.Default.Tune,"Positions" to Icons.Default.ShowChart,"MT5" to Icons.Default.AccountBalance,"Settings" to Icons.Default.Settings).forEachIndexed{i,x->NavigationBarItem(tab==i,{tab=i},{Icon(x.second,x.first)},{Text(x.first,fontSize=10.sp)},colors=NavigationBarItemDefaults.colors(selectedIconColor=Cyan,selectedTextColor=Cyan,unselectedIconColor=Muted,unselectedTextColor=Muted,indicatorColor=Raised))}}}){p->when(tab){0->Home(c,Modifier.padding(p));1->Strategies(Modifier.padding(p));2->Positions(c,Modifier.padding(p));3->Mt5(c,Modifier.padding(p));else->Settings(Modifier.padding(p))}}}}
@Composable private fun Home(c:Context,m:Modifier){val api=remember{BackendStateClient()};val scope=rememberCoroutineScope();var session by remember{mutableStateOf<String?>(null)};var state by remember{mutableStateOf<BackendState?>(null)};var running by remember{mutableStateOf(false)};var busy by remember{mutableStateOf(false)};var message by remember{mutableStateOf("")};val pulse=rememberInfiniteTransition(label="pulse").animateFloat(1f,1.06f,infiniteRepeatable(tween(900),RepeatMode.Reverse),label="pulse")
 LaunchedEffect(Unit){session=c.prefs.data.first()[Keys.SESSION];while(true){val s=session;if(!s.isNullOrBlank()){api.state(s).onSuccess{state=it;message=""}.onFailure{message=it.message?:"Backend unavailable"}};delay(5000)}}
 LazyColumn(m.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp),contentPadding=PaddingValues(bottom=24.dp)){item{Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween,Alignment.CenterVertically){Column{Text("PIPS-LIFE",color=Txt,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("TRADING CONTROL CENTER",color=Muted,fontSize=11.sp,letterSpacing=1.4.sp)};Pill(if(state?.connectionStatus.equals("CONNECTED",true))"MT5 LIVE" else if(session!=null)"BACKEND LINKED" else "NO MT5")}}
 item{Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(22.dp)){Column(Modifier.fillMaxWidth().padding(20.dp),Alignment.CenterHorizontally){Text("BOT STATUS",color=Muted,fontSize=11.sp,letterSpacing=1.5.sp);Spacer(Modifier.height(10.dp));Box(Modifier.size(88.dp).scale(pulse.value),Alignment.Center){Box(Modifier.fillMaxSize().border(2.dp,if(running)Green else Line,CircleShape));Box(Modifier.size(58.dp).background(if(running)Green.copy(alpha=.12f) else Raised,CircleShape));Box(Modifier.size(13.dp).background(if(running)Green else Muted,CircleShape))};Spacer(Modifier.height(10.dp));Text(if(running)"RUNNING" else "STOPPED",color=if(running)Green else Txt,fontSize=22.sp,fontWeight=FontWeight.Bold);Text("Strategy 001 • QOF",color=Muted,fontSize=12.sp);Spacer(Modifier.height(15.dp));Button(enabled=session!=null&&!busy,onClick={val s=session?:return@Button;busy=true;scope.launch{runCatching{api.bot(s,!running)}.onSuccess{x->running=x.running;message=if(x.running)"MT5 backend connection started." else "MT5 backend connection stopped."}.onFailure{message=it.message?:"Bot control failed"};busy=false}}){Text(if(running)"STOP BOT" else "START BOT")};Text(message,color=Muted,fontSize=10.sp)}}}
 if(state!=null){item{Section("ACCOUNT",state!!.login)};item{Account(state!!)};item{Section("ACTIVE POSITIONS","${state!!.positions.size} open")};items(state!!.positions){Position(it)}}else{item{Section("LIVE DATA","Awaiting MT5")};item{Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Text(if(session==null)"Connect your MT5 account from the MT5 tab. Live account data will replace all placeholders." else "Waiting for MetaApi to connect to the broker…",color=Muted,fontSize=12.sp,modifier=Modifier.padding(16.dp))}}};item{Section("STRATEGIES","Expandable")};item{Strategy("001","QOF","PRIMARY • READY",true)};item{Strategy("002","Reserved","FUTURE STRATEGY SLOT",false)};item{Strategy("003","Reserved","FUTURE STRATEGY SLOT",false)}}}
@Composable private fun Account(s:BackendState){Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Text(s.server,color=Txt,fontWeight=FontWeight.Bold);Text(s.connectionStatus,color=if(s.connectionStatus.equals("CONNECTED",true))Green else Cyan,fontSize=10.sp,fontWeight=FontWeight.Bold)};Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Metric("BALANCE",money(s.balance,s.currency));Metric("EQUITY",money(s.equity,s.currency));Metric("TRADING",if(s.tradeAllowed)"ALLOWED" else "BLOCKED")}}}}
@Composable private fun Position(p:BackendPosition){Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Column{Text(p.symbol,color=Txt,fontSize=17.sp,fontWeight=FontWeight.Bold);Text("${p.side} • ${p.volume} lot",color=Cyan,fontSize=11.sp,fontWeight=FontWeight.Bold)};Text(money(p.profit,"USD"),color=if(p.profit>=0)Green else Red,fontSize=17.sp,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Metric("ENTRY",number(p.entry));Metric("CURRENT",number(p.current));Metric("SL",number(p.stopLoss));Metric("TP",number(p.takeProfit))}}}}
@Composable private fun Positions(c:Context,m:Modifier){val api=remember{BackendStateClient()};var s by remember{mutableStateOf<BackendState?>(null)};LaunchedEffect(Unit){val t=c.prefs.data.first()[Keys.SESSION];if(!t.isNullOrBlank())api.state(t).onSuccess{s=it}};LazyColumn(m.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("POSITIONS",color=Txt,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Live positions from MT5.",color=Muted,fontSize=12.sp)};if(s==null)item{Text("No live MT5 account connected.",color=Muted)}else items(s!!.positions){Position(it)}}}
@Composable private fun Mt5(c:Context,m:Modifier){val scope=rememberCoroutineScope();val api=remember{Mt5ApiClient()};var broker by remember{mutableStateOf("")};var login by remember{mutableStateOf("")};var pass by remember{mutableStateOf("")};var server by remember{mutableStateOf("")};var servers by remember{mutableStateOf(emptyList<Mt5Server>())};var busy by remember{mutableStateOf(false)};var msg by remember{mutableStateOf("")};LaunchedEffect(Unit){val p=c.prefs.data.first();broker=p[Keys.BROKER].orEmpty();login=p[Keys.LOGIN].orEmpty();server=p[Keys.SERVER].orEmpty();if(p[Keys.SESSION]!=null)msg="MT5 session linked to backend."}
 LazyColumn(m.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp),contentPadding=PaddingValues(bottom=20.dp)){item{Text("MT5 ACCOUNT",color=Txt,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Credentials go to the Pips-life backend over HTTPS; the MetaApi token remains server-side.",color=Muted,fontSize=12.sp)};item{Field(broker,{broker=it},"Broker name")};item{Button(enabled=broker.length>=2&&!busy,onClick={busy=true;scope.launch{runCatching{api.findServers(broker)}.onSuccess{servers=it;msg="Select your exact MT5 server."}.onFailure{msg=it.message?:"Server discovery failed"};busy=false}}){Text(if(busy)"SEARCHING…" else "FIND SERVERS")}};items(servers){x->Card(onClick={server=x.serverName},colors=CardDefaults.cardColors(containerColor=Panel),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(14.dp)){Text(x.brokerName,color=Muted,fontSize=10.sp);Text(x.serverName,color=Txt,fontWeight=FontWeight.Bold);if(server==x.serverName)Text("SELECTED",color=Green,fontSize=10.sp)}}};item{Field(server,{server=it},"MT5 server")};item{Field(login,{login=it},"MT5 account number")};item{OutlinedTextField(pass,{pass=it},Modifier.fillMaxWidth(),label={Text("MT5 password")},singleLine=true,visualTransformation=PasswordVisualTransformation())};item{Button(enabled=login.isNotBlank()&&pass.isNotBlank()&&server.isNotBlank()&&!busy,onClick={busy=true;msg="Connecting through Pips-life backend…";scope.launch{runCatching{api.connect(login,pass,server,broker)}.onSuccess{x->if(x.accountId.isNullOrBlank()||x.sessionToken.isNullOrBlank())msg="Backend did not return a session." else{c.prefs.edit{it[Keys.ACCOUNT]=x.accountId;it[Keys.SESSION]=x.sessionToken;it[Keys.BROKER]=broker;it[Keys.SERVER]=server;it[Keys.LOGIN]=login};pass="";msg="Backend linked • ${x.connectionStatus}"}}.onFailure{msg=it.message?:"MT5 connection failed"};busy=false}}){Text(if(busy)"CONNECTING…" else "CONNECT MT5 TO BACKEND")}};item{Text(msg,color=Muted,fontSize=12.sp)}}}
@Composable private fun Strategies(m:Modifier){LazyColumn(m.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("STRATEGIES",color=Txt,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Strategy 001 is primary; future slots remain reserved.",color=Muted,fontSize=12.sp)};item{Strategy("001","QOF","PRIMARY • READY",true)};item{Strategy("002","Reserved","FUTURE STRATEGY SLOT",false)};item{Strategy("003","Reserved","FUTURE STRATEGY SLOT",false)}}}
@Composable private fun Settings(m:Modifier){Column(m.fillMaxSize().background(Ink).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text("SETTINGS",color=Txt,fontSize=25.sp,fontWeight=FontWeight.Bold);Text("Pips-life 0.2.1 (3)",color=Muted);Text("Live MT5 → backend data layer enabled. No purple palette.",color=Muted,fontSize=12.sp)}}
@Composable private fun Field(v:String,set:(String)->Unit,label:String){OutlinedTextField(v,set,Modifier.fillMaxWidth(),label={Text(label)},singleLine=true)}
@Composable private fun Pill(t:String){Row(Modifier.background(Panel,RoundedCornerShape(50)),verticalAlignment=Alignment.CenterVertically){Box(Modifier.padding(start=10.dp).size(8.dp).background(if(t=="MT5 LIVE")Green else Muted,CircleShape));Text(" $t",color=Muted,fontSize=10.sp,modifier=Modifier.padding(end=10.dp))}}
@Composable private fun Section(a:String,b:String){Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween,Alignment.Bottom){Text(a,color=Txt,fontSize=13.sp,fontWeight=FontWeight.Bold);Text(b,color=Muted,fontSize=10.sp)}}
@Composable private fun Metric(a:String,b:String){Column{Text(a,color=Muted,fontSize=9.sp);Text(b,color=Txt,fontSize=12.sp,fontWeight=FontWeight.SemiBold)}}
@Composable private fun Strategy(n:String,name:String,state:String,active:Boolean){Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(16.dp)){Row(Modifier.fillMaxWidth().padding(14.dp),Alignment.CenterVertically){Text(n,color=if(active)Cyan else Muted,fontWeight=FontWeight.Bold,modifier=Modifier.width(40.dp));Column(Modifier.weight(1f)){Text(name,color=Txt,fontWeight=FontWeight.Bold);Text(state,color=if(active)Green else Muted,fontSize=10.sp)};Icon(Icons.Default.ChevronRight,null,tint=Muted)}}}
private fun money(v:Double,c:String)=String.format("%s %.2f",c,v);private fun number(v:Double)=if(v==0.0)"—" else String.format("%.2f",v)
